head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDisabled]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 disabled 상태를 설정합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 disabled 상태를 설정할 Body Cell 의 Column ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="초기 모든 Cell enable 상태 / setCellDisabled 의 colInfo 에 Column ID 를 사용하여 Cell 단위 disabled 동작 검증 (disabled=회색 배경)"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (초기 모든 Cell enable 상태, 상위 단위 disabled 미설정)
    await $c.gcm.createBasicGridView(cList);
}



scwin.btn_setCellDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = par_colInfo.getValue();
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 → 기본값 false
        target1.setCellDisabled(rowIndex, colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", \"" + colInfo + "\")");
    } else if (disabledText === '') {
        // 빈 문자열 설정 → 상위 모듈 disabled 적용
        target1.setCellDisabled(rowIndex, colInfo, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", \"" + colInfo + "\", '')");
    } else {
        let disabled = disabledText === 'true';
        target1.setCellDisabled(rowIndex, colInfo, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setCellDisabled(" + rowIndex + ", \"" + colInfo + "\", " + disabled + ")");
    }

    scwin.btn_getCellDisabled_onclick();
}



scwin.btn_getCellDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = par_colInfo.getValue();

    // Cell 단위 disabled 상태 (getCellDisabled)
    let cellRtn = target1.getCellDisabled(rowIndex, colInfo);
    // 최종 적용된 실제 disabled 상태 (getDisabled('all') : GridView/Row/Column/Cell 우선순위 반영)
    let allRtn = target1.getDisabled("all", rowIndex, colInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getCellDisabled(" + rowIndex + ", \"" + colInfo + "\") [Cell 단위] : " + cellRtn);
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('all', " + rowIndex + ", \"" + colInfo + "\") [최종 적용] : " + allRtn);
}
